/** Furnishing groups are selected by the work done here; their footprints block movement. */
export const REALISM_ATLAS={kitchen:0,dining:1,joinery:2,sleeping:3,treatment:4,reading:5,textiles:6,ceramics:7,pumping:8,hydrophone:9,pantry:10,reception:11};
const f=(id,w,h,label,visual,text)=>({id,w,h,label,visual,text,detail:text+' The fittings stand together as a working station, with a clear approach for the person using them.'});
export function roomFixtures(kind,key){
 const culinary=[f(3,3,2,'Preparation counter','kitchen','Pans hang over a scrubbed worktop. A chopping board and clean basin keep food preparation separate from the ash of the range.'),f(19,2,2,'Open food stores','pantry','Heavy grain sacks stand low, crockery above them. The oldest provisions face the kitchen, ready for the next meal.')];
 if(['home','quarters','nursery'].includes(kind))return [f(0,3,3,'Bed and bedside belongings','sleeping','A quilt, a coat and a small bedside cabinet make this a sleeping corner rather than a bed abandoned in the middle of the room.'),...culinary,f(5,3,2,'Household meal table','dining','Four used places share bread and a linen runner. The chairs face one another, leaving a way through to the hearth.')];
 if(['inn','mess','kitchen','assembly','refuge'].includes(kind))return [...culinary,f(5,3,2,'Shared meal table','dining','Bowls and mismatched mugs are arranged around a common meal. The serving side is kept clear of the circulation aisle.'),f(7,3,2,'Arrival and service counter','reception','Keys, an open ledger and travelling coats belong beside the entrance, where new arrivals can find the keeper.')];
 if(kind==='clinic')return [f(11,3,3,'Treatment bay','treatment','The bed, clean basin, medicine trolley and privacy curtain form one treatment bay. Used cloth is kept away from the fresh linen.'),f(10,2,2,'Remedy preparation',null,'Labelled medicines occupy the upper shelves. Clean cups and sealed dressings wait below, within easy reach of the attendant.')];
 if(['archive','guild','waiting','printshop'].includes(kind))return [f(2,3,2,'Shelves and reading desk','reading','Open folios lie beside the archive shelves. The lamp, index and reading surface are within reach of the same chair.'),f(7,3,2,'Public service desk','reception','The public counter faces the approach. Work in progress stays behind it, leaving the visitor a clear place to set down a document.')];
 if(kind==='tailor')return [f(21,3,2,'Cutting and stitching station','textiles','The cutting cloth lies flat beside the treadle machine. Thread reels and shears wait where the worker can reach them without crossing the room.')];
 if(kind==='pottery'||key==='pottery_floor')return [f(8,3,2,'Wheel and drying rack','ceramics','The wet clay, wheel and drying rack follow the order of the work. The finished pots stand away from the splash of the basin.')];
 if(['listening','music','chapel','instrumentworks'].includes(kind))return [f(23,3,2,'Reed, string and water instrument','hydrophone','A water bowl, reed rack and string soundboard share a vibration bridge. The listening seat faces the instrument rather than the wall.'),f(2,3,2,'Score library and copying desk','reading','Scores are stored beside the surface where they are copied. The current part is held flat under a brass lamp.')];
 if(['cistern'].includes(kind)||/vent|spill|reactor|console/.test(key))return [f(8,3,2,'Pump and maintenance platform','pumping','The flywheel, pressure gauge and relief pipes form one serviceable circuit. Its controls face a dry working approach.'),f(9,3,2,'Repair and inspection bench','joinery','Tools hang over the repair surface. The inspected components stay separate from the parts awaiting attention.')];
 if(['cargo','store'].includes(kind))return [f(19,3,2,'Open provision shelving','pantry','Stock is sorted by use on open shelves. There is room to inspect a container without unpacking a tower of sealed crates.'),f(7,3,2,'Receiving counter','reception','The receiving ledger faces the loading approach. Tags and returned straps stay on the work side of the counter.')];
 return [f(8,3,2,'Fitted craft station','joinery','A vice, tools and the unfinished work share a long bench. Shavings gather beneath the work surface, clear of the main aisle.'),f(2,3,2,'Plans and reference shelf','reading','The working plans are kept beside the reference shelves, away from the grit and filings of the active bench.')];
}
export function realisticFixture(o,kind,key){if(o.supply)return null;const matches=roomFixtures(kind,key).filter(f=>f.id===o.furniture);return matches[0]||null;}
